package cep

import (
	"context"

	"github.com/cloudwego/kitex/pkg/streaming"
)

// Endpoint is a client-side endpoint that handles the entire request/response cycle.
// It includes context for request-scoped operations.
type Endpoint func(ctx context.Context, req, resp interface{}) error

// StreamEndpoint is a client-side endpoint for streaming RPCs.
// It receives request and returns a streaming.ClientStream for further operations.
type StreamEndpoint func(ctx context.Context, req interface{}) (streaming.ClientStream, error)

// UnaryEndpoint is a client-side endpoint specifically for unary (non-streaming) RPCs.
// This is semantically equivalent to Endpoint but provides clearer intent.
type UnaryEndpoint func(ctx context.Context, req, resp interface{}) error

// Middleware is a chainable wrapper around an Endpoint.
type Middleware func(Endpoint) Endpoint

// StreamMiddleware is a chainable wrapper around a StreamEndpoint.
type StreamMiddleware func(StreamEndpoint) StreamEndpoint

// UnaryMiddleware is a chainable wrapper around a UnaryEndpoint.
type UnaryMiddleware func(UnaryEndpoint) UnaryEndpoint

// MiddlewareBuilder builds a middleware with information from a context.
type MiddlewareBuilder func(ctx context.Context) Middleware

// StreamMiddlewareBuilder builds a stream middleware with information from a context.
type StreamMiddlewareBuilder func(ctx context.Context) StreamMiddleware

// UnaryMiddlewareBuilder builds a unary middleware with information from a context.
type UnaryMiddlewareBuilder func(ctx context.Context) UnaryMiddleware

// Chain connects multiple middlewares into one middleware.
func Chain(mws ...Middleware) Middleware {
	return func(next Endpoint) Endpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// StreamChain connects multiple stream middlewares into one middleware.
func StreamChain(mws ...StreamMiddleware) StreamMiddleware {
	return func(next StreamEndpoint) StreamEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// UnaryChain connects multiple unary middlewares into one middleware.
func UnaryChain(mws ...UnaryMiddleware) UnaryMiddleware {
	return func(next UnaryEndpoint) UnaryEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// DummyMiddleware is a no-op middleware for testing.
func DummyMiddleware(next Endpoint) Endpoint {
	return next
}

// DummyStreamMiddleware is a no-op stream middleware for testing.
func DummyStreamMiddleware(next StreamEndpoint) StreamEndpoint {
	return next
}

// DummyUnaryMiddleware is a no-op unary middleware for testing.
func DummyUnaryMiddleware(next UnaryEndpoint) UnaryEndpoint {
	return next
}

// DummyEndpoint is a dummy endpoint for testing.
func DummyEndpoint(ctx context.Context, req, resp interface{}) error {
	return nil
}

